import { useRef, type CSSProperties, type KeyboardEvent } from "react";

import { useReducedMotion } from "@/hooks/useReducedMotion";
import RealmsNightSky from "./RealmsNightSky";

export type EntryId = "casual" | "focused" | "competitive";

type EntrySelectorProps = {
  value: EntryId;
  onChange: (next: EntryId, source?: "pointer" | "keyboard") => void;
};

/**
 * Three routes across one realm, listed west to east as they sit on the map. The terrain is generated by scripts/generate-realms-entry-map.ts;
 * MAP_FEATURES mirrors the hill positions there so each route ends on the ground it describes.
 */
const entries = [
  {
    id: "competitive",
    label: "Competitive",
    reason: "Face another team",
    routes: [
      // Both sides meet at the foot of the flag, so the two routes read as one contested line.
      "M480 440C400 412 356 362 320 304C292 258 276 214 248 180",
      "M12 92C58 90 108 102 156 124C190 140 222 150 248 180",
    ],
    end: { x: 248, y: 172 },
    rival: { x: 12, y: 92 },
    // Below-left of the summit, clear of both routes so the label never cuts a line.
    labelAt: { x: 232, y: 214, anchor: "end" },
  },
  {
    id: "focused",
    label: "Focused",
    reason: "Pursue a field",
    routes: ["M480 440C482 390 506 350 500 300S474 222 480 180"],
    end: { x: 480, y: 165 },
    labelAt: { x: 460, y: 150, anchor: "end" },
  },
  {
    id: "casual",
    label: "Casual",
    reason: "Follow the unknown",
    routes: ["M480 440C508 418 542 410 558 384C576 354 546 330 574 306C604 282 642 320 674 300C706 280 682 252 714 240C730 234 742 232 754 228"],
    end: { x: 754, y: 228 },
    labelAt: { x: 754, y: 262, anchor: "middle" },
  },
] as const;

const TRAILHEAD = { x: 480, y: 440 };

// Each mode moves at its own pace: a wander, a steady climb, a race to the same summit.
const TRAVEL: Record<EntryId, { seconds: number; ease: string }> = {
  casual: { seconds: 9, ease: "cubic-bezier(.45, 0, .55, 1)" },
  focused: { seconds: 4.2, ease: "linear" },
  competitive: { seconds: 2.4, ease: "cubic-bezier(.3, 0, .2, 1)" },
};

function Marker({ id, x, y }: { id: EntryId; x: number; y: number }) {
  if (id === "focused") return <path className="route-marker" d={`M${x} ${y - 9}l8 13h-16Z`} />;
  // A flag planted on the contested summit: whoever gets there first holds it.
  if (id === "competitive") {
    return <path className="route-marker" d={`M${x - 1} ${y + 8}V${y - 15}h15l-4.5 6 4.5 6H${x + 1}V${y + 8}Z`} />;
  }
  return <circle className="route-marker route-marker--open" cx={x} cy={y} r="6.5" />;
}

export default function RealmsEntrySelector({ value, onChange }: EntrySelectorProps) {
  const reduce = useReducedMotion();
  const tabRefs = useRef<Record<EntryId, HTMLButtonElement | null>>({ casual: null, focused: null, competitive: null });

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, currentId: EntryId) {
    const currentIndex = entries.findIndex((entry) => entry.id === currentId);
    let nextIndex: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        nextIndex = (currentIndex + 1) % entries.length;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        nextIndex = (currentIndex + entries.length - 1) % entries.length;
        break;
      case "Home":
        nextIndex = 0;
        break;
      case "End":
        nextIndex = entries.length - 1;
        break;
      default:
        return;
    }
    event.preventDefault();
    const next = entries[nextIndex].id;
    onChange(next, "keyboard");
    tabRefs.current[next]?.focus();
  }

  return (
    <div className="route-selector" data-selected={value}>
      <div className="route-map">
        <div className="route-map-terrain" aria-hidden="true" />
        {entries.map((entry) => (
          <div key={entry.id} className={`route-map-terrain route-map-terrain--${entry.id}`} aria-hidden="true" />
        ))}
        <svg className="route-map-overlay" viewBox="0 0 960 460" aria-hidden="true">
          {entries.map((entry) => {
            const selected = value === entry.id;
            return (
              <g
                key={entry.id}
                className={`route route--${entry.id}${selected ? " is-selected" : ""}`}
                onClick={() => onChange(entry.id, "pointer")}
              >
                {entry.routes.map((d) => (
                  <g key={d}>
                    <path className="route-hit" d={d} />
                    <path className="route-trail" d={d} />
                    <path className="route-casing" d={d} pathLength={1} />
                    <path className="route-line" d={d} pathLength={1} />
                    {selected && !reduce && (
                      <path
                        className="route-pulse"
                        d={d}
                        pathLength={1}
                        style={{ "--travel": `${TRAVEL[entry.id].seconds}s`, "--travel-ease": TRAVEL[entry.id].ease } as CSSProperties}
                      />
                    )}
                  </g>
                ))}
                {"rival" in entry && <circle className="route-rival" cx={entry.rival.x} cy={entry.rival.y} r="5" />}
                <Marker id={entry.id} x={entry.end.x} y={entry.end.y} />
                <text className="route-label" x={entry.labelAt.x} y={entry.labelAt.y} textAnchor={entry.labelAt.anchor}>
                  {entry.label}
                </text>
              </g>
            );
          })}
          {!reduce && value === "casual" && <RealmsNightSky />}
          <g className="route-start">
            <circle cx={TRAILHEAD.x} cy={TRAILHEAD.y} r="11" className="route-start-ring" />
            <circle cx={TRAILHEAD.x} cy={TRAILHEAD.y} r="4.5" />
          </g>
        </svg>
      </div>

      <div className="route-legend" role="tablist" aria-label="Find your way into Realms">
        {entries.map((entry) => {
          const selected = value === entry.id;
          return (
            <button
              key={entry.id}
              ref={(node) => { tabRefs.current[entry.id] = node; }}
              type="button"
              role="tab"
              id={`entry-${entry.id}`}
              aria-selected={selected}
              aria-controls={`path-${entry.id}`}
              tabIndex={selected ? 0 : -1}
              className={`route-tab route-tab--${entry.id}`}
              onClick={(event) => onChange(entry.id, event.detail === 0 ? "keyboard" : "pointer")}
              onKeyDown={(event) => handleKeyDown(event, entry.id)}
            >
              <span className="route-tab-name">{entry.label}</span>
              <span className="route-tab-reason">{entry.reason}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
